    "slug": "custom-hooks",
    "title": "Custom Hook Examples",
    "desc": "<h2>useFetch Hook</h2>\n<p>This custom hook fetches data from an API and handles loading and error states.</p>\n<div style={{ textAlign: 'left' }}>\n```jsx\n  import { useState, useEffect } from 'react';<p>  function useFetch(url) {\n    const [data, setData] = useState(null);\n    const [loading, setLoading] = useState(true);\n    const [error, setError] = useState(null);</p>\n<pre><code>useEffect(() =&gt; {\n  const fetchData = async () =&gt; {\n    try {\n      const response = await fetch(url);\n      if (!response.ok) {\n        throw new Error(&#39;Network response was not ok&#39;);\n      }\n      const data = await response.json();\n      setData(data);\n\n    } catch (error) {\n      setError(error);\n    } finally {\n      setLoading(false);\n    }\n  };\n  fetchData();\n}, [url]);\n\nreturn { data, loading, error };\n</code></pre>\n<p>  }\n  export default useFetch;</p>\n<pre><code>&lt;/div&gt;\n\n## Usage in a Component:\n\n&lt;div style={{ textAlign: &#39;left&#39; }}&gt;\n```jsx\n  import React from &#39;react&#39;;\n  import useFetch from &#39;./useFetch&#39;;\n\n  function DataDisplay({ url }) {\n    \n    const { data, loading, error } = useFetch(url);\n    if (loading) return &lt;div&gt;Loading...&lt;/div&gt;;\n    if (error) return &lt;div&gt;Error: {error.message}&lt;/div&gt;;\n\n    return (\n      &lt;div&gt;\n        &lt;pre&gt;{JSON.stringify(data, null, 2)}&lt;/pre&gt;\n      &lt;/div&gt;\n    );\n  }\n  export default DataDisplay;\n</code></pre>\n</div><h2>Example 2: useLocalStorage Hook</h2>\n<p>This custom hook manages state synchronized with localStorage.</p>\n<div style={{ textAlign: 'left' }}>\n```jsx\n  import { useState } from 'react';<p>  function useLocalStorage(key, initialValue) {\n    const [storedValue, setStoredValue] = useState(() =&gt; {\n      try {\n        const item = window.localStorage.getItem(key);\n        return item ? JSON.parse(item) : initialValue;\n      } catch (error) {\n        console.log(error);\n        return initialValue;\n      }\n    });</p>\n<pre><code>const setValue = value =&gt; {\n  try {\n    const valueToStore = value instanceof Function ? value(storedValue) : value;\n    setStoredValue(valueToStore);\n    window.localStorage.setItem(key, JSON.stringify(valueToStore));\n  } catch (error) {\n    console.log(error);\n  }\n};\n\nreturn [storedValue, setValue];\n</code></pre>\n<p>  }\n  export default useLocalStorage;</p>\n<pre><code>&lt;/div&gt;\n</code></pre>\n",
